export type ParsedSettleProtectionInstruction<
  TProgram extends string = typeof WASHAPP_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    pool: TAccountMetas[0];
    protection: TAccountMetas[1];
    pvault: TAccountMetas[2];
    contract: TAccountMetas[3];
    lossEvent: TAccountMetas[4];
    buyerAta: TAccountMetas[5];
    tokenProgram: TAccountMetas[6];
  };
  data: SettleProtectionInstructionData;
};

export function parseSettleProtectionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSettleProtectionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      pool: getNextAccount(),
      protection: getNextAccount(),
      pvault: getNextAccount(),
      contract: getNextAccount(),
      lossEvent: getNextAccount(),
      buyerAta: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getSettleProtectionInstructionDataDecoder().decode(instruction.data),
  };
}
